 LinearLayout dates=new LinearLayout(this);LinearLayout a=choice("DEPARTURE");dep=text("Select date",15,DARK);a.addView(dep);a.setOnClickListener(v->date(false));dates.addView(a,p(0,70,1));dates.addView(gap(8),p(8,1,0));LinearLayout b=choice("RETURN");ret=text("Select date",15,DARK);b.addView(ret);b.setOnClickListener(v->{if(round)date(true);});dates.addView(b,p(0,70,1));searchCard.addView(dates);searchCard.addView(gap(9));
