 LinearLayout choice(String s){LinearLayout x=box(0xfff7f4ef,17);x.setPadding(12,7,12,4);TextView l=text(s,9,ORANGE);l.setTypeface(Typeface.DEFAULT,1);x.addView(l);return x;}
 EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine();e.setTextSize(16);e.setTextColor(DARK);e.setHintTextColor(0xff999ba1);e.setPadding(16,0,16,0);e.setBackground(border(0xfff7f4ef,LINE,17));e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int a,int b,int c){suggest(e,s.toString());}});return e;}
 void suggest(EditText e,String q){ViewGroup par=(ViewGroup)e.getParent();int i=par.indexOfChild(e);if(i+1<par.getChildCount()&&"drop".equals(par.getChildAt(i+1).getTag()))par.removeViewAt(i+1);if(q.trim().isEmpty())return;ArrayList<String[]>m=new ArrayList<>();String z=q.toLowerCase(Locale.US);for(String[]a:airports)if((a[0]+" "+a[1]+" "+a[2]+" "+a[3]).toLowerCase(Locale.US).contains(z))m.add(a);Collections.shuffle(m,random);int n=Math.min(5,m.size());if(n==0)return;LinearLayout d=box(Color.WHITE,18);d.setTag("drop");d.setPadding(5,5,5,5);d.setElevation(16);for(int k=0;k<n;k++){String[]a=m.get(k);LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);TextView dot=text("●",11,ORANGE);r.addView(dot,p(28,54,0));LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.addView(text(a[0],15,DARK));info.addView(text(a[1]+"  •  "+a[2]+"  •  "+a[3],11,MUTED));r.addView(info,p(0,54,1));final String value=a[0]+" ("+a[2]+")";r.setOnClickListener(v->{e.setText(value);e.setSelection(value.length());d.setVisibility(View.GONE);});d.addView(r,p(-1,54,0));}par.addView(d,i+1,p(-1,-2,0));}
 void date(boolean returning){Calendar c=Calendar.getInstance();DatePickerDialog d=new DatePickerDialog(this,(v,y,m,day)->{String x=String.format(Locale.US,"%02d/%02d/%04d",day,m+1,y);if(returning){retDate=x;ret.setText(x);}else{depDate=x;dep.setText(x);if(round)date(true);}},c.get(1),c.get(2),c.get(5));d.setTitle(returning?"Return date":"Departure date");d.show();}
 void travellersDialog(){new AlertDialog.Builder(this).setTitle("Travellers").setItems(new String[]{"1 adult","2 adults","3 adults","4 adults","2 adults • 1 child","2 adults • 1 infant"},(d,w)->travellers.setText(new String[]{"1 adult","2 adults","3 adults","4 adults","2 adults • 1 child","2 adults • 1 infant"}[w])).show();}
 void cabinDialog(){String[]x={"Economy","Premium Economy","Business","First"};new AlertDialog.Builder(this).setTitle("Cabin class").setSingleChoiceItems(x,Arrays.asList(x).indexOf(cabin.getText().toString()),(d,w)->{cabin.setText(x[w]);d.dismiss();}).show();}
 void search(){if(from.getText().toString().trim().isEmpty()||to.getText().toString().trim().isEmpty()){toast("Choose From and To.");return;}if(depDate.isEmpty()||(round&&retDate.isEmpty())){toast("Choose both travel dates.");return;}((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(from.getWindowToken(),0);searchCard.animate().translationY(-30).alpha(.12f).setDuration(300).withEndAction(()->{searchCard.setVisibility(View.GONE);showResults();}).start();}
 void showResults(){results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);results.setPadding(0,4,0,20);body.addView(results,p(-1,-2,0));results.setAlpha(0);results.animate().alpha(1).setDuration(450).start();LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView h=text("Flight results",26,DARK);h.setTypeface(Typeface.DEFAULT,1);top.addView(h,p(0,55,1));Button f=outline("Filters");f.setOnClickListener(v->filterDialog());top.addView(f,p(95,44,0));results.addView(top);LinearLayout route=box(0xffffeee3,18);route.setPadding(15,12,15,12);route.addView(text(from.getText()+"  →  "+to.getText(),16,DARK));route.addView(text(depDate+(round?"  •  "+retDate:"")+"  •  "+cabin.getText(),12,MUTED));results.addView(route,p(-1,-2,0));results.addView(gap(12));
 LinearLayout empty=box(Color.WHITE,25);empty.setGravity(17);empty.setPadding(24,32,24,32);TextView plane=text("✈",48,ORANGE);plane.setGravity(17);empty.addView(plane);TextView title=text("Live search connected by architecture",21,DARK);title.setGravity(17);title.setTypeface(Typeface.DEFAULT,1);empty.addView(title);TextView msg=text("This build never invents flights or prices. Connect a real Flight API through the Vicationfly backend to populate live results.",14,MUTED);msg.setGravity(17);empty.addView(msg);Button retry=outline("Try live search");retry.setOnClickListener(v->toast("No real provider credentials are configured in this APK."));empty.addView(retry,p(-1,52,0));results.addView(empty,p(-1,-2,0));results.addView(gap(12));TextView note=text("Before booking, Vicationfly must revalidate availability and price with the provider.",11,MUTED);results.addView(note);Button back=outline("New search");back.setOnClickListener(v->{results.setVisibility(View.GONE);searchCard.setVisibility(View.VISIBLE);searchCard.setAlpha(1);searchCard.setTranslationY(0);});results.addView(back,p(-1,54,0));}
 void filterDialog(){String[]x={"Cheapest","Fastest","Best","Non-stop","1 stop or fewer","Morning departure","Evening departure"};new AlertDialog.Builder(this).setTitle("Filters & sorting").setMultiChoiceItems(x,null,null).setPositiveButton("Apply",null).setNegativeButton("Cancel",null).show();}
